import 'package:flutter/material.dart';

/// Zeigt einen Bestätigungsdialog an, um den Benutzer zu fragen, ob er die Fahrt beenden möchte.
/// Die Callback-Funktionen [onConfirm] und [onCancel] werden bei Betätigung der jeweiligen Buttons aufgerufen.
Future<void> showEndRideConfirmationDialog(BuildContext context, {required VoidCallback onConfirm, required VoidCallback onCancel}) async {
  return showDialog<void>(
    context: context,
    barrierDismissible: true, // Der Dialog kann durch Tippen außerhalb geschlossen werden
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text("Fahrt beenden?"),
        content: const Text("Möchten Sie wirklich die Fahrt beenden und die Daten speichern?"),
        actions: <Widget>[
          // Der "Nein" Button ist neutral/abbrechend
          TextButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Dialog schließen
              // Hier kann optional ein onCancelDialogTapped() Aufruf erfolgen, falls gewünscht
            },
            child: const Text("Nein"),
          ),
          // Der "Ja" Button ist die Bestätigung/Aktion
          ElevatedButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Dialog schließen
              onConfirm(); // Die bestätigte Aktion ausführen (z.B. Daten speichern)
            },
            style: ElevatedButton.elevation(0),
            child: const Text("Ja", style: TextStyle(color: Colors.red)),
          ),
        ],
      );
    },
  );
}

