import 'package:flutter/material.dart';

/// Zeigt einen Bestätigungsdialog "Fahrt beenden?" an und wartet auf die Benutzereingabe.
/// 
/// Erfordert ein BuildContext, um den Dialog zu zeigen.
///
/// [onConfirm] wird ausgeführt, wenn der Benutzer 'Ja' tippt (Bestätigung).
/// [onCancel] wird ausgeführt, wenn der Benutzer 'Nein' tippt oder den Dialog schließt (Abbruch).
Future<T> showEndTripConfirmation<T>(BuildContext context, {
  required Future<T> Function() onConfirm,
  required Future<T?> Function() onCancel,
}) async {
  // Wir verwenden showDialog, um sicherzustellen, dass der CallStack ordentlich verwaltet wird.
  return await showDialog<T>(
    context: context,
    barrierDismissible: false, // Benutzer muss auf einen Button tippen
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text('Fahrt beenden?'),
        content: const Text('Sind Sie sicher, dass Sie die Fahrt endgültig beenden möchten?'),
        actions: <Widget>[
          // Nein-Button (Abbruch/Cancel)
          TextButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Schließt den Dialog und signalisiert Abbruch
              // Hier könnten Sie auch den onCancel-Handler direkt aufrufen, 
              // wenn der Aufruf innerhalb des State-Kontexts funktioniert.
              // Für saubere Separation lassen wir die Logik beim Aufrufer (car_home_screen) laufen.
            },
            child: const Text('Nein', style: TextStyle(color: Colors.grey)),
          ),
          // Ja-Button (Bestätigung/Confirm)
          ElevatedButton(
            onPressed: () {
              Navigator.of(dialogContext).pop(); // Schließt den Dialog und signalisiert Bestätigung
              // Wir geben einen spezifischen Wert zurück, um dem onConfirm Handler zu signalisieren.
            },
            child: const Text('Ja'),
          ),
        ],
      );
    },
  ) ?? null;
}

