import 'package:flutter/material.dart';

/// Zeigt den Bestätigungsdialog "Fahrt beenden?" an.
///
/// Dieser Dialog wird von einem Button-Handler in car_home_screen.dart aufgerufen.
/// WICHTIGER HINWEIS: In diesem Repository muss showDialog idealerweise durch 
/// eine spezialisierte Funktionalität ersetzt werden, die den Dialog als Vollbild-Overlay
/// pusht (z.B. AppCoreService.showConfirmationSheet(context)), um den bekannten Weissraum-Bug zu vermeiden.
void showTripEndingDialog({
  required BuildContext context,
  required Function() onConfirm, // Wird aufgerufen, wenn der Nutzer "Ja" tippt (Fahrt beenden)
  required Function() onCancel, // Wird aufgerufen, wenn der Nutzer "Nein" tippt oder annulliert
}) {
  showDialog(
    context: context,
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text('Fahrt beenden?'),
        content: const Text("Möchten Sie die aktuell aufgezeichnete Fahrt manuell beenden?"),
        actions: <Widget>[
          // 1. Nein Button (Abbrechen/Warten)
          TextButton(
            onPressed: () {
              // Schliesst den Dialog und ruft das Abbrechen-Callback auf
              Navigator.of(dialogContext).pop();
              if (onCancel != null) onCancel!();
            },
            child: const Text('Nein'),
          ),
          // 2. Ja Button (Bestätigen/Abschliessen)
          ElevatedButton(
            style: ElevatedButton.gradient(
                // Nutze hier idealerweise die Hauptmarkenfarbe der App
                begin: Colors.red, end: Colors.deepOrange), 
            onPressed: () {
              // Schliesst den Dialog und ruft das Bestätigen-Callback auf
              Navigator.of(dialogContext).pop();
              if (onConfirm != null) onConfirm!();
            },
            child: const Text('Ja'), // Die Aktion ist "Fahrt beenden"
          ),
        ],
      );
    },
  );
}

