class TripService {
  /// Gibt einen Future zurück, der true ist, wenn die Fahrt beendet werden soll (Ja), und false sonst (Nein).
  Future<bool> confirmEndTrip() async {
    return await showDialog<void>(
      context: context,
      barrierDismissible: false, // Der Benutzer muss auf einen Button tippen
      builder: (BuildContext dialogContext) {
        return AlertDialog(
          title: const Text('Fahrt beenden?'),
          content: const Text('Sind Sie sicher, dass Sie die aktuelle Fahrt beenden möchten? Diese Aktion kann nicht rückgängig gemacht werden.'),
          actions: <Widget>[
            // Button für Nein (Abbrechen)
            TextButton(
              onPressed: () {
                Navigator.of(dialogContext).pop(false); // Ergebnis: false
              },
              child: const Text('Nein'),
            ),
            // Separator ist oft besser als direkt aneinandergereihte Buttons
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 8.0),
              child: Text('?', style: Theme.of(dialogContext).textTheme.bodyMedium!),
            ),
            // Button für Ja (Bestätigen)
            ElevatedButton(
              onPressed: () {
                Navigator.of(dialogContext).pop(true); // Ergebnis: true
              },
              child: const Text('Ja'),
            ),
          ],
        );
      },
    ) ?? false; // Falls der Dialog ignoriert wird (z.B. durch System-Pop), defaultmäßig auf 'Nein' setzen.
  }

  /// Hauptlogik, die im CarHomeScreen aufgerufen wird.
  Future<void> handleEndTripAction(BuildContext context) async {
    // 1. Bestätigungsdialog anzeigen und Ergebnis abwarten
    final bool shouldEndTrip = await confirmEndTrip();

    if (shouldEndTrip) {
      // 2. Hier die tatsächliche Geschäftslogik einfügen:
      // Beispiel: TripRepository.endCurrentTrip();
      print('Fahrt wurde erfolgreich beendet. Logging...');
      // UI-Update, z.B. Rückkehr zur Startansicht oder Anzeige einer Erfolgsmeldung.
    } else {
      print('Fahrtenbeendigung abgebrochen.');
    }
  }
}

